#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
python3 -m unittest discover -s tests -p 'test_*.py' -v
for test in test_combat test_combat_order test_combat_death_wait_flee test_combat_merge test_combat_timeline test_combat_layout test_card_target_pose test_individual_pose_spawns test_impact_feedback test_combat_presentation test_stacking test_cycle_order test_cycle_timeline test_cycle_save_validation test_cycle_presentation test_puff_view test_puff_events test_vendor_unlock_sequence test_vendor_unlock_presenter test_card_interaction_feedback test_navigation_input test_card_drag_input test_card_motion test_title_gameplay_prefs test_title_navigation test_title_navigation_board test_scene_transition test_world_post_process test_text_button_feedback test_menu_slide test_day_clock test_journal_groups test_placement_lifecycle test_navigation_ui test_collection test_trade_layout test_vendor_payment test_spawn_factory test_save_codec test_held_stack test_crafting_order test_ai_placement_order test_ai_detach_craft test_purchase_craft test_travel_checkpoint_globals test_recipe_card_definition test_save_slots test_slot_management test_user_options test_special_recipe_scenes test_visual_assets test_card_mesh_binding test_card_overlays test_combat_sprite_binding test_equipment_display test_puff_simulation test_board_layout test_source_camera test_camera_motion test_audio_feedback test_ui_smoke test_gui_layout; do
  bash tools/test_godot.sh "res://tests/godot/$test.gd"
done
if [[ -f data/stackcraft.json ]]; then
  python3 tools/verify_source.py --data data
  for test in test_board_integration test_cycle_board test_cycle_action_visibility test_source_recipe_cards test_purchase_craft_source test_travel_checkpoint_globals_source test_held_stack_source test_held_stack_board test_card_drag_board test_card_motion_board test_title_gameplay_prefs_board test_day_clock_board test_scene_transition_board test_world_post_process_board test_chest_click_lifecycle test_source_card_interaction test_crafting_order_source test_crafting_order_board test_ai_placement_board test_ai_detach_craft_source test_card_feedback_board test_puff_board test_camera_board test_trade_collection_ui test_vendor_unlock_board test_options_ui test_combat_feedback_ui test_equipment_board test_slot_ui test_slot_management_ui test_combat_board test_trade_currency test_scene_spawn test_world_rules test_runtime test_special_recipes test_quests test_quest_integration test_travel test_mob_ai; do
    bash tools/test_godot.sh "res://tests/godot/$test.gd"
  done
else
  echo 'SOURCE-DATA SUITES SKIPPED: import licensed data for full domain regression checks.'
fi
